function P = cw_params(studentID)
%CW_PARAMS  Personal parameters for EEEE3116 Coursework 1 and 2 (2026/27).
%   P = cw_params(studentID)   studentID = your 8-digit student ID (numeric)
%   Do not edit this file. Your submission is checked with these values.

    if ~isnumeric(studentID) || ~isscalar(studentID) || studentID < 1e6 || studentID >= 2^32
        error('cw_params:ID', 'Enter your numeric student ID, e.g. cw_params(20512345)');
    end
    rng(double(studentID), 'twister');           % reproducible on any MATLAB version

    letters = 'ACDEFHJKLMNPRTUVWXY3479';           % no easily confused characters
    P.code  = letters(randi(numel(letters), 1, 4));  % write this on paper for photo C

    t1 = [99.0 99.3 99.5 99.7 99.9];
    P.cw1.T = t1(randi(numel(t1)));                % CW1 energy target (%)
    t2 = [80 85 90 95];
    P.cw2.T = t2(randi(numel(t2)));                % CW2 variance target (%)

    if nargout == 0
        fprintf('Student %d\n', studentID);
        fprintf('  Code word for photo C : %s\n', P.code);
        fprintf('  CW1 energy target T   : %.1f %%\n', P.cw1.T);
        fprintf('  CW2 variance target T : %d %%\n', P.cw2.T);
    end
end
